node --version && node --input-type=module -e "
import { backoffDelay } from './src/retry.js';
for (const a of [0,1,2,5,6]) {
  let neg=0, min=Infinity, max=-Infinity; const N=100000;
  for (let i=0;i<N;i++){ const d=backoffDelay(a); if(d<=0)neg++; min=Math.min(min,d); max=Math.max(max,d); }
  console.log('attempt',a,'<=0:',(neg/N*100).toFixed(1)+'%','min',min.toFixed(0),'max',max.toFixed(0));
}
setTimeout(()=>console.log('negative timeout fired'), -300);
" 2>&1; node --test test/ 2>&1 | tail -8
